from collections import Counter
def rearange_string(s):
  count_dict = Counter(s)
  max_count = max(count_dict.values())
  if max_count > len(s)//2:
    return "Not possible"
  else:
    sorted_chars = sorted(count_dict.keys(), key=lambda x: count_dict[x])
    result = []
    while max_count > 0:
      for char in sorted_chars:
        if count_dict[char] > 0:
          result.append(char)
          count_dict[char] -= 1
          max_count -= 1
    return ''.join(result)
